/* Large laptops use workflow/guidance as drawers. The permanent left column is
   reserved for the active task's controls so the canvas gets the working area. */
@media (max-width: 1399.98px) {
  .guidedStudioBody {
    display: block;
  }

  .guidedStepRail {
    position: fixed;
    z-index: 80;
    top: 58px;
    left: 0;
    bottom: 0;
    width: min(320px, 92vw);
    transform: translateX(-100%);
    transition: transform 0.18s ease;
    box-shadow: 16px 0 40px rgba(0, 0, 0, 0.45);
  }

  .guidedStepRail.isOpen {
    transform: translateX(0);
  }

  .guidedStudioTopbarActions .guidedMobileControl,
  .guidedStepRail .guidedDrawerClose {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .guidedMainWorkspace {
    width: 100%;
    height: calc(100dvh - 58px);
  }

  /* Marker placement already has the same view controls in the canvas toolbar.
     Keep the left task rail focused on landmarks instead of duplicating buttons. */
  .guidedStudioStep--2 .referenceWorkspace .sidebar .controls,
  .guidedStudioStep--2 .referenceWorkspace .sidebar > h2:first-child {
    display: none;
  }

  .guidedStudioStep--2 .referenceWorkspace .sidebar > .hint {
    margin-top: 0;
  }
}

/* On the laptop marker workspace the collapsed reference control belongs to the
   task rail. It must not float across the current-landmark header and canvas. */
@media (min-width: 992px) and (max-width: 1399.98px) {
  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed {
    top: 10px;
    left: 10px;
    width: min(230px, calc(100% - 20px));
    padding: 8px 10px;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeading {
    gap: 6px;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeading h2 {
    font-size: 12px;
    letter-spacing: 0.08em;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeadingActions button {
    padding: 7px 8px;
    font-size: 12px;
    white-space: nowrap;
  }

  .guidedStudioStep--2 .referenceWorkspace .sidebar {
    padding-top: 66px;
  }
}

/* Short laptop browser viewports need compact marketing sections, but they still
   scroll naturally instead of trying to squeeze the whole explanation on screen. */
@media (max-height: 760px) and (min-width: 992px) {
  .landingPipeline {
    padding: 34px 0 26px;
    scroll-margin-top: 60px;
  }

  .landingPipeline h2 {
    max-width: 680px;
    margin: 7px 0 20px;
    font-size: clamp(30px, 3vw, 40px);
  }

  .landingPipeline ol {
    gap: 8px;
  }

  .landingPipeline li {
    min-height: 92px;
    padding: 14px;
  }

  .landingTiles {
    gap: 14px;
    padding-bottom: 48px;
  }

  .landingTiles article {
    min-height: 0;
    padding: 20px;
  }

  .landingTiles h2 {
    margin: 18px 0 8px;
    font-size: 21px;
  }

  .guidedStepRail,
  .guidedInspector {
    top: 52px;
  }

  .guidedMainWorkspace {
    height: calc(100dvh - 52px);
  }
}

@media (max-width: 680px) {
  .landingPipeline {
    scroll-margin-top: 68px;
  }

  .guidedStudioTopbarActions {
    gap: 5px;
  }

  .guidedStudioTopbarActions button {
    padding: 7px 8px;
    font-size: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .landingExperience {
    scroll-behavior: auto;
  }

  .guidedStepRail {
    transition: none;
  }
}

/* Reference controls participate in layout instead of covering marker tools. */
.studioApplicationShell .referenceManager.collapsed {
  position: relative;
  inset: auto;
  width: auto;
  flex: 0 0 auto;
  margin: 8px;
  box-shadow: none;
}
.studioApplicationShell .guidedMainWorkspace { overflow-y: auto; }
.studioApplicationShell .workspace { overflow-y: auto; }
.markerReview { flex: 0 0 auto; padding: 8px; border: 1px solid #46506c; border-radius: 8px; margin-bottom: 8px; }
.markerReview p { font-size: 13px; overflow-wrap: anywhere; }
.markerReview > div { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }
.markerReview button { padding: 8px 10px; background: #24293a; color: #fff; border: 1px solid #7180aa; border-radius: 7px; cursor: pointer; }
.markerReview button:disabled { opacity: .5; cursor: not-allowed; }
.studioApplicationShell .referenceWorkspace .sidebar { padding-top: 12px; }

